import {List as Material} from "./0Describing the UI/section1"

export default function () {
  return (
    <>
    <Loop/>
    </>
  );
}

function Count({c}) {
  return <li>now {c}</li>
}

function Loop({amount}) {
  let list = []
  for(let i=1; i<=amount; i++) {
    list.push(<Count c={i}/>)
  }
  return <ul>{list}</ul>
}
